CREATE TABLE IF NOT EXISTS "git_repositories" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" uuid NOT NULL, "project_id" uuid, "provider" varchar(16) NOT NULL DEFAULT 'github', "owner" varchar(255) NOT NULL, "repo" varchar(255) NOT NULL, "webhook_secret" text NOT NULL, "is_active" boolean NOT NULL DEFAULT true, "last_event_at" timestamp, "last_error" text, "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), "deleted_at" timestamp, CONSTRAINT "git_repositories_organization_id_organizations_id_fk" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE NO ACTION ON UPDATE NO ACTION, CONSTRAINT "git_repositories_project_id_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON DELETE NO ACTION ON UPDATE NO ACTION);--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "git_repos_owner_repo_idx" ON "git_repositories" USING btree ("organization_id","owner","repo");--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "git_links" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" uuid NOT NULL, "repository_id" uuid NOT NULL, "card_id" uuid NOT NULL, "kind" varchar(16) NOT NULL, "ref" varchar(512) NOT NULL, "url" varchar(2048), "title" varchar(500), "state" varchar(32) NOT NULL DEFAULT 'open', "author" varchar(255), "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), "deleted_at" timestamp, CONSTRAINT "git_links_repository_id_git_repositories_id_fk" FOREIGN KEY ("repository_id") REFERENCES "git_repositories"("id") ON DELETE NO ACTION ON UPDATE NO ACTION, CONSTRAINT "git_links_card_id_cards_id_fk" FOREIGN KEY ("card_id") REFERENCES "cards"("id") ON DELETE NO ACTION ON UPDATE NO ACTION);--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "git_links_card_ref_idx" ON "git_links" USING btree ("card_id","kind","ref");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "git_links_repo_idx" ON "git_links" USING btree ("repository_id");
